-- APPROVAL-0174 phone-label remediation. Six v2 path swaps; preserve data/VRs.
begin;
set local lock_timeout='3s';
set local statement_timeout='20s';
create temporary table phone_targets on commit drop as
select * from jsonb_to_recordset($targets$[{"content_key": "apcalcab-frq-u13-002", "version_id": "d0f2974c-bac9-498d-8173-8a1c88b3d8eb", "old_path": "questions/apcalcab-frq-u13-002/v1/63000031e6860d5fd51bf8f10c6fafa9d64bf3fcda059933414c712c69eec674.png", "path": "questions/apcalcab-frq-u13-002/v2/bca6ca68b5511794b7d0ade184214609a8e95a34b97498a9cb5e160d7a5b3508.png", "audit_content_digest": "7f095e64e222b728818543808f4d79dd", "alt": "Coordinate graph of g on the interval from −4 to 4. Three line segments and open and filled endpoint markers are shown.", "long_description": "The graph contains a segment from the filled point (−4, −2) to an open point at (−1, 4); a filled point at (−1, 1); a horizontal segment for −1 < x < 2 at height 1 with an open point at (2, 1); and a segment from the filled point (2, 3) to the filled point (4, −1)."}, {"content_key": "apcalcab-frq-u13g-1-3", "version_id": "a59eb1ed-b96e-4d89-94ee-a4a32b309744", "old_path": "questions/apcalcab-frq-u13g-1-3/v1/c49e3a59682394ec52b3b72b4186c86ab7f46ab1bc9e00d1f6c0fce8a6f3f257.png", "path": "questions/apcalcab-frq-u13g-1-3/v2/75702de6d4bdfbfe04aaf0e102df9f824e0d6cbd9950b2296b40e93e034ab377.png", "audit_content_digest": "88c7a8ad1e5bc82e95549f0553d09ad2", "alt": "Coordinate graph of g from −4 to 6, with two line segments, isolated filled points, two curved branches and a dashed vertical line at x = 4.", "long_description": "A segment runs from filled (−4, 0) to open (−1, 3), with an isolated filled point at (−1, 1). Another segment runs from open (−1, −2) to open (2, 4); (2, 0) is filled. On 2 < x < 4 a continuous increasing curve starts near (2, 4) and continues upward beside x = 4. On 4 < x ≤ 6 a continuous decreasing curve continues upward beside x = 4 and ends at filled (6, 1). There is no point at x = 4."}, {"content_key": "apcalcab-oht-1.3", "version_id": "f1548706-2043-4f7b-9941-c1c6e2724174", "old_path": "questions/apcalcab-oht-1.3/v1/76c37ed79953f2a2dbad6a958275ef7f817edd7e0d62039f121c9563427a6fbe.png", "path": "questions/apcalcab-oht-1.3/v2/ac7fd89a433124ad8e567adcac94e49a17c95e739f151e724c9a5248d34a7478.png", "audit_content_digest": "29894c021b001dd5396513c775e639fe", "alt": "Coordinate graph of p showing a straight left branch, a filled point at (3, 5), and a curved right branch beginning at an open point at (3, 2).", "long_description": "For x < 3, the graph follows y = x + 2. The point (3, 5) is filled. For x > 3, the graph follows y = x² − 7 and has an open point at (3, 2). Arrows indicate continuation beyond the displayed window."}, {"content_key": "apchem-oht-3.8", "version_id": "b7b068cb-0610-4da7-8565-4290621d402f", "old_path": "questions/apchem-oht-3.8/v1/61f844d30f28abd72d1293e09f543d25be8a9e8b2bcd00305c983d27d7b30c45.png", "path": "questions/apchem-oht-3.8/v2/66fbf35180965b903ef15df42a6c6dd13b01b18da4ecf6961a6bbd513f9b2967.png", "audit_content_digest": "9b6371fd488da7cd307e499bd89169f0", "alt": "Two solution diagrams use identical dots for the same solute. Diagram 1 is labelled 100 mL and contains eight dots; diagram 2 is labelled 200 mL and contains sixteen dots.", "long_description": "Diagram 1 contains eight solute particles in a box representing 100 mL of solution. Diagram 2 contains sixteen particles of the same solute in a box representing 200 mL. Dots have the same size in both diagrams. The boxes are schematic; the printed volumes are the stated solution volumes. No concentration comparison is labelled."}, {"content_key": "apcalcab-mcq-060", "version_id": "f492bfbf-5434-434f-a4d8-50b058477139", "old_path": "questions/apcalcab-mcq-060/v1/aeebaee24dc1fbea1b833ac7e165bf3750c18905daea509843b434d51feec81d.png", "path": "questions/apcalcab-mcq-060/v2/9c8307b50c0c5c345f016df04cb96f8cca7bf5f88ebcf3645700f53c567e4669.png", "audit_content_digest": "d3e3e7b8e7861a67230f3fb4182ecf9e", "alt": "Coordinate graph of g showing a straight left branch, a curved right branch, an open point at (3, 4), and an isolated filled point at (3, 6).", "long_description": "For x < 3 the graph follows y = x + 1. For x > 3 it follows y = −(x − 3)² + 4. The point (3, 4) is open and (3, 6) is filled. Arrows indicate continuation beyond the displayed window."}, {"content_key": "apchem-frq-u13g-3-8", "version_id": "959822a0-5cd4-4e1f-813e-58241c6c66cf", "old_path": "questions/apchem-frq-u13g-3-8/v1/04f69c1149733ea80a002f1704dca6b81c1f02f4a9e008bea36d13796794827b.png", "path": "questions/apchem-frq-u13g-3-8/v2/86914cd4eb4e2a171de085a3a7ddb0d1b60f0e35fb7d56edad82059e9fc2ebad.png", "audit_content_digest": "61632ec722ec128b424e8741210e062e", "alt": "Equal-volume solution models P and Q show separated ions. P is labelled 0.30 M NaCl and Q is labelled CaCl₂. Water molecules are omitted.", "long_description": "Model P contains six Na⁺ ions and six Cl⁻ ions. Model Q contains four Ca²⁺ ions and eight Cl⁻ ions. The equal-size boxes represent the same small volume of solution. Each ion is separate; no water molecules, water orientations, or calculated concentrations are shown."}]$targets$::jsonb)
as r(content_key text,version_id uuid,old_path text,path text,audit_content_digest text,alt text,long_description text);
do $guard$ begin
if (select count(*) from phone_targets)<>6 then raise exception 'Expected six phone targets'; end if;
perform v.id from app.content_item_versions v join phone_targets t on t.version_id=v.id order by v.id for update of v;
perform c.choice_key from app.mcq_choices c join phone_targets t on t.version_id=c.content_item_version_id order by c.choice_key for update of c;
perform m.content_item_version_id from app.content_asset_metadata m join phone_targets t on t.version_id=m.content_item_version_id order by m.content_item_version_id,m.storage_path for update of m;
perform r.content_item_version_id from app.content_visual_requirements r join phone_targets t on t.version_id=r.content_item_version_id order by r.content_item_version_id for update of r;
if (select count(*) from phone_targets t join app.content_item_versions v on v.id=t.version_id join app.content_items ci on ci.id=v.content_item_id
 join app.content_visual_requirements r on r.content_item_version_id=v.id join app.content_asset_metadata m on m.content_item_version_id=v.id and m.storage_bucket='content-assets' and m.storage_path=t.old_path
 where ci.content_key=t.content_key and ci.status='published' and v.status='published' and v.stimulus_image_path=t.old_path and r.image_needed='yes' and r.image_approval='approved' and m.approved_at is not null and md5(jsonb_build_object('stem',v.stem,'stimulus',v.stimulus,
 'choices',coalesce((select jsonb_agg(jsonb_build_object('key',c.choice_key,'text',c.choice_text) order by c.choice_key) from app.mcq_choices c where c.content_item_version_id=v.id),'[]'::jsonb),
 'parts',coalesce((select jsonb_agg(jsonb_build_object('key',coalesce(p.part->>'part_key',p.part->>'part_id',p.ordinality::text),'text',coalesce(nullif(p.part->>'prompt',''),p.part->>'prompt_text')) order by p.ordinality)
 from jsonb_array_elements(case when jsonb_typeof(v.prompt_json->'parts')='array' then v.prompt_json->'parts' when jsonb_typeof(v.item_package_payload->'parts')='array' then v.item_package_payload->'parts' else '[]'::jsonb end) with ordinality as p(part,ordinality)
 where jsonb_typeof(p.part)='object' and (jsonb_typeof(p.part->'prompt')='string' or jsonb_typeof(p.part->'prompt_text')='string') and nullif(btrim(coalesce(nullif(p.part->>'prompt',''),p.part->>'prompt_text')),'') is not null),'[]'::jsonb),
 'prompt',v.prompt_json,'package',v.item_package_payload,'image_path',null::text)::text)=t.audit_content_digest)<>6 then raise exception 'Reviewed source/path/approval drift'; end if;
if exists(select 1 from phone_targets t left join storage.objects o on o.bucket_id='content-assets' and o.name=t.path where o.id is null) then raise exception 'New private object absent'; end if;
if exists(select 1 from app.content_asset_metadata m join phone_targets t on m.content_item_version_id=t.version_id and m.storage_bucket='content-assets' and m.storage_path=t.path) then raise exception 'Unexpected v2 metadata'; end if;
end $guard$;
create temporary table phone_before on commit drop as
select v.id,v.content_item_id,md5((to_jsonb(v)-'stimulus_image_path'-'updated_at')::text) content_hash,app.taxonomy_relevant_hash(v.id) taxo_hash,
(select md5(jsonb_agg(to_jsonb(c) order by c.choice_key)::text) from app.mcq_choices c where c.content_item_version_id=v.id) choice_hash,
(select md5(to_jsonb(r)::text) from app.content_visual_requirements r where r.content_item_version_id=v.id) requirement_hash,
(select md5(jsonb_agg(to_jsonb(l) order by l.content_taxonomy_label_id)::text) from app.content_taxonomy_labels l where l.content_item_id=v.content_item_id) label_hash
from app.content_item_versions v join phone_targets t on t.version_id=v.id;
update app.content_item_versions v set stimulus_image_path=t.path from phone_targets t where v.id=t.version_id;
insert into app.content_asset_metadata(content_item_version_id,storage_bucket,storage_path,alt_text,long_description,approved_by,approved_at)
select version_id,'content-assets',path,alt,long_description,'f5a26c6b-3566-4d58-9e97-979fbb947564',now() from phone_targets;
do $verify$ begin
if (select count(*) from phone_targets t join app.content_item_versions v on v.id=t.version_id join app.content_asset_metadata m on m.content_item_version_id=v.id and m.storage_path=t.path and m.storage_bucket='content-assets' where v.stimulus_image_path=t.path and m.alt_text=t.alt and m.long_description=t.long_description and m.approved_at is not null)<>6 then raise exception 'New paths/metadata not complete'; end if;
if exists(select 1 from phone_before b join app.content_item_versions v on v.id=b.id where md5((to_jsonb(v)-'stimulus_image_path'-'updated_at')::text)<>b.content_hash or app.taxonomy_relevant_hash(v.id)<>b.taxo_hash
or (select md5(jsonb_agg(to_jsonb(c) order by c.choice_key)::text) from app.mcq_choices c where c.content_item_version_id=v.id) is distinct from b.choice_hash
or (select md5(to_jsonb(r)::text) from app.content_visual_requirements r where r.content_item_version_id=v.id) is distinct from b.requirement_hash
or (select md5(jsonb_agg(to_jsonb(l) order by l.content_taxonomy_label_id)::text) from app.content_taxonomy_labels l where l.content_item_id=v.content_item_id) is distinct from b.label_hash) then raise exception 'Question/scoring/choice/taxonomy/decision drift'; end if;
end $verify$;
commit;
